insert into public.courses (id, language, dialect, title, description, cefr_level, goal_tag, position, published, school, prerequisite_ids)
values ('bbbb0002-0000-4000-8000-00000000000d', 'en', null, 'Spreadsheets: Excel & Google Sheets', 'Build practical spreadsheet fluency — from cell references and formulas to lookups, pivot tables, and dashboards — using Excel and Google Sheets side by side. Assembled from openly-licensed OER Commons material (CC BY).', null, 'work', 13, true, 'technology', '{bbbb0002-0000-4000-8000-000000000001}')
on conflict (id) do nothing;

insert into public.lessons (course_id, position, title, kind, body, grammar_notes_md, estimated_minutes)
select 'bbbb0002-0000-4000-8000-00000000000d', v.pos, v.title, v.kind, v.body::jsonb, v.notes, v.mins
from (values
  (1, 'Diagnostic: where are you now?', 'quiz', '{"questions":[{"prompt":"In a spreadsheet, the box where a row and a column meet is called a…","options":["formula","cell","sheet","range"],"answer":1,"explanation":"A single box is a cell; a rectangle of cells is a range."},{"prompt":"Which of these is a formula rather than plain text?","options":["A1+B1","SUM total","=A1+B1","the sum of A1 and B1"],"answer":2,"explanation":"Formulas begin with = in both Excel and Google Sheets."},{"prompt":"Which reference stays fixed when you copy a formula down a column?","options":["A1","$A$1","A$1 only for rows","1A"],"answer":1,"explanation":"The dollar signs in $A$1 lock both the column and the row — an absolute reference."},{"prompt":"Which function adds up a range of numbers?","options":["AVERAGE","COUNT","SUM","IF"],"answer":2,"explanation":"SUM totals a range; AVERAGE gives the mean."},{"prompt":"```=AVERAGE(B2:B6)``` returns the…","options":["largest value","arithmetic mean","count of cells","first value"],"answer":1,"explanation":"AVERAGE divides the sum by how many numbers there are."},{"prompt":"Which function looks up a value by matching the first column of a table?","options":["VLOOKUP","SUMIF","TRIM","CONCAT"],"answer":0,"explanation":"VLOOKUP scans the leftmost column and returns a value from a column to its right."},{"prompt":"A pivot table is mainly used to…","options":["change fonts","summarize and group large amounts of data","protect a sheet with a password","insert images"],"answer":1,"explanation":"Pivot tables aggregate rows into compact summaries by category."},{"prompt":"```=IF(A1>10,\"Yes\",\"No\")``` returns \"Yes\" when…","options":["A1 is exactly 10","A1 is greater than 10","A1 is blank","A1 is text"],"answer":1,"explanation":"The test A1>10 is true only for values strictly above 10."}]}'::jsonb, null, 10),
  (2, 'Cells, references, and your first formulas', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Write basic formulas and choose between relative and absolute references. Warm-up: from the diagnostic, which reference — A1 or $A$1 — stays fixed when you copy a formula?"},{"heading":"The idea","text":"Every formula starts with an equals sign and can point at other cells by their address, like B2 (column B, row 2). A *relative* reference such as B2 shifts as you copy the formula: copy it one row down and it becomes B3. An *absolute* reference such as ```$B$1``` is locked by the dollar signs and never moves. A simple example: to add two cells you write ```=A2+B2```; to multiply a price by a shared tax rate stored in F1 you write ```=B2*$F$1``` so the rate stays anchored as you fill down."},{"heading":"Worked examples","text":"Say A2 holds 10 and B2 holds 5. Then ```=A2+B2``` gives 15, ```=A2-B2``` gives 5, ```=A2*B2``` gives 50, and ```=A2/B2``` gives 2. Now put a tax rate of 0.1 in F1 and a price of 200 in B2. The formula ```=B2*$F$1``` returns 20. Copy it down to B3 (price 350) and it becomes ```=B3*$F$1```, returning 35 — the $F$1 never drifted."},{"heading":"Your turn","text":"With A2 = 8 and B2 = 4, predict each result: (1) ```=A2+B2```, (2) ```=A2*B2```, (3) ```=A2/B2```, (4) ```=A2-B2```. Expected: (1) 12, (2) 32, (3) 2, (4) 4. Bonus (5): if F1 = 0.2 and B2 = 50, what does ```=B2*$F$1``` return? Expected: 10."},{"heading":"Common mistakes & exit ticket","text":"Mistake: forgetting the leading = , so the cell shows text instead of calculating. Mistake: leaving a rate reference relative, so it slides to an empty cell when copied. Exit: (a) What symbol makes a reference absolute? (b) Copy ```=A2+B2``` from row 2 to row 3 — what does it become? Answers: the dollar sign, giving $A$2; it becomes ```=A3+B3```."}]}'::jsonb, 'Relative references (A1) shift when copied; absolute references ($A$1) stay put.', 12),
  (3, 'Essential functions: SUM, AVERAGE, IF, COUNTIF', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Total, average, test, and count data with four everyday functions. Warm-up: which function would you use to find the mean of a column of scores?"},{"heading":"The idea","text":"Functions are named formulas that take arguments in parentheses. ```=SUM(B2:B6)``` adds a range. ```=AVERAGE(B2:B6)``` gives its mean. ```=IF(B2>=60,\"Pass\",\"Fail\")``` returns one of two results based on a test. ```=COUNTIF(B2:B6,\">=60\")``` counts how many cells meet a condition — the condition is written as text in quotes. All four work identically in Excel and Google Sheets."},{"heading":"Worked examples","text":"Put these five scores in B2:B6: 80, 55, 90, 70, 45. Then ```=SUM(B2:B6)``` returns 340. ```=AVERAGE(B2:B6)``` returns 68 (340 ÷ 5). ```=IF(B2>=60,\"Pass\",\"Fail\")``` reads B2 = 80 and returns \"Pass\". ```=COUNTIF(B2:B6,\">=60\")``` counts 80, 90, and 70 for a result of 3."},{"heading":"Your turn","text":"Using the same values 80, 55, 90, 70, 45 in B2:B6, predict each: (1) ```=SUM(B2:B6)```, (2) ```=AVERAGE(B2:B6)```, (3) ```=COUNTIF(B2:B6,\"<60\")```, (4) ```=IF(B3>=60,\"Pass\",\"Fail\")``` where B3 = 55, (5) ```=MAX(B2:B6)```. Expected: (1) 340, (2) 68, (3) 2, (4) \"Fail\", (5) 90."},{"heading":"Common mistakes & exit ticket","text":"Mistake: writing the COUNTIF condition without quotes, e.g. COUNTIF(B2:B6,>=60), which errors — it must be ```\">=60\"```. Mistake: mixing text and numbers in a range so SUM silently ignores the text. Exit: (a) What does ```=COUNTIF(B2:B6,\">=60\")``` count? (b) What are the two possible outputs of ```=IF(B2>=60,\"Pass\",\"Fail\")```? Answers: the cells that are 60 or higher; \"Pass\" or \"Fail\"."}]}'::jsonb, 'COUNTIF counts cells that meet a condition; put the condition in quotes, like ">=60".', 13),
  (4, 'Lookups: VLOOKUP, XLOOKUP, and INDEX-MATCH', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Pull a matching value out of a table three different ways. Warm-up: which classic function only works when the lookup column is on the left of the answer?"},{"heading":"The idea","text":"A lookup finds a row by a key and returns a value from that row. ```=VLOOKUP(\"Banana\",A2:B5,2,FALSE)``` searches column A for \"Banana\" and returns the value in the 2nd column of the range; FALSE forces an exact match. The newer ```=XLOOKUP(\"Banana\",A2:A5,B2:B5)``` names the search range and the return range separately (available in Excel 365 and Google Sheets). ```=INDEX(B2:B5,MATCH(\"Banana\",A2:A5,0))``` does the same by finding the row number with MATCH and then reading that row with INDEX — and unlike VLOOKUP it can return a column to the left of the key."},{"heading":"Worked examples","text":"Build a price list: A2:A5 = Apple, Banana, Cherry, Date and B2:B5 = 0.50, 0.30, 0.80, 1.20. All three of ```=VLOOKUP(\"Banana\",A2:B5,2,FALSE)```, ```=XLOOKUP(\"Banana\",A2:A5,B2:B5)```, and ```=INDEX(B2:B5,MATCH(\"Banana\",A2:A5,0))``` return 0.30. Looking up \"Date\" the same way returns 1.20, and \"Apple\" returns 0.50."},{"heading":"Your turn","text":"With that price list, predict each: (1) ```=VLOOKUP(\"Cherry\",A2:B5,2,FALSE)```, (2) ```=XLOOKUP(\"Apple\",A2:A5,B2:B5)```, (3) ```=INDEX(B2:B5,MATCH(\"Date\",A2:A5,0))```, (4) ```=MATCH(\"Cherry\",A2:A5,0)```, (5) ```=VLOOKUP(\"Grape\",A2:B5,2,FALSE)```. Expected: (1) 0.80, (2) 0.50, (3) 1.20, (4) 3, (5) an #N/A error because \"Grape\" is not in the list."},{"heading":"Common mistakes & exit ticket","text":"Mistake: omitting FALSE in VLOOKUP, which switches to approximate match and can return the wrong row on unsorted data. Mistake: expecting VLOOKUP to look leftward — it cannot; use INDEX-MATCH or XLOOKUP instead. Exit: (a) What does the FALSE argument in VLOOKUP guarantee? (b) Which two lookups can return a value to the left of the key? Answers: an exact match; INDEX-MATCH and XLOOKUP."}]}'::jsonb, 'VLOOKUP searches left-to-right; INDEX-MATCH and XLOOKUP can look in any direction.', 14),
  (5, 'Checkpoint 1', 'quiz', '{"questions":[{"prompt":"In ```=A2*$B$1```, the ```$B$1``` part is a…","options":["relative reference","absolute reference","range name","function"],"answer":1,"explanation":"The dollar signs lock the reference so it never shifts when copied."},{"prompt":"For the values 80, 55, 90, 70, 45 in B2:B6, ```=SUM(B2:B6)``` returns…","options":["68","340","5","90"],"answer":1,"explanation":"80 + 55 + 90 + 70 + 45 = 340."},{"prompt":"For those same values, ```=COUNTIF(B2:B6,\">=60\")``` returns…","options":["2","3","5","340"],"answer":1,"explanation":"Only 80, 90, and 70 meet the condition, so the count is 3."},{"prompt":"The FALSE in ```=VLOOKUP(\"Banana\",A2:B5,2,FALSE)``` means…","options":["approximate match","exact match","sort the table","hide errors"],"answer":1,"explanation":"FALSE (or 0) requires an exact match on the lookup value."},{"prompt":"For 80, 55, 90, 70, 45 in B2:B6, ```=AVERAGE(B2:B6)``` returns…","options":["68","70","340","60"],"answer":0,"explanation":"340 divided by 5 values equals 68."},{"prompt":"One advantage of INDEX-MATCH over VLOOKUP is that it can…","options":["only sort data","return a value left of the lookup column","count cells","format currency"],"answer":1,"explanation":"INDEX-MATCH is direction-independent, so the answer can sit to the left of the key."}]}'::jsonb, null, 8),
  (6, 'Sorting, filtering, and data validation', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Reorder rows, show only the rows you want, and control what people can type. Warm-up: which menu feature stops someone entering \"banana\" where a date belongs?"},{"heading":"The idea","text":"Sorting reorders rows by a column; filtering hides rows that fail a test; data validation restricts what a cell will accept. You can do all three from the Data menu, or with formulas: ```=SORT(A2:B10,2,FALSE)``` returns the range sorted by its 2nd column in descending order (FALSE = descending), and ```=FILTER(A2:B10,B2:B10>100)``` returns only the rows where column B exceeds 100. Data validation (Data ▸ Data validation) can force a cell to hold, say, a value from a dropdown list or a number in a range."},{"heading":"Worked examples","text":"Suppose A2:A10 holds names and B2:B10 holds sales 120, 90, 200, 80, 150, 60, 300, 40, 110. Then ```=FILTER(A2:B10,B2:B10>100)``` keeps only the rows with 120, 200, 150, 300, and 110 — five rows. ```=SORT(A2:B10,2,FALSE)``` lists those same nine rows from 300 down to 40. A validation rule set to \"greater than 0\" would reject a typed value of -5 and show a warning."},{"heading":"Your turn","text":"Using sales 120, 90, 200, 80, 150, 60, 300, 40, 110 in B2:B10, predict: (1) how many rows ```=FILTER(A2:B10,B2:B10>100)``` returns, (2) the top value after ```=SORT(A2:B10,2,FALSE)```, (3) the result of ```=FILTER(A2:B10,B2:B10>=300)```, (4) whether validation \"number between 1 and 100\" accepts 250. Expected: (1) 5, (2) 300, (3) the single row with 300, (4) no — 250 is out of range."},{"heading":"Common mistakes & exit ticket","text":"Mistake: sorting only one column of a table so its rows detach from their labels — always select the whole table. Mistake: assuming FILTER changes the original data (it returns a new spilled result and leaves the source untouched). Exit: (a) Does FALSE in SORT mean ascending or descending? (b) What is data validation for? Answers: descending; to restrict what can be entered in a cell."}]}'::jsonb, 'SORT and FILTER are dynamic array functions; the Data menu offers one-click versions of the same actions.', 12),
  (7, 'Pivot tables: summarizing data fast', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Turn a long list of records into a compact by-category summary. Warm-up: if you had 10,000 sales rows, what tool would total them by region in seconds?"},{"heading":"The idea","text":"A pivot table groups your rows by one field (the *rows* area, e.g. Region) and summarizes another (the *values* area, e.g. Sum of Sales). You build it from the menu — Insert ▸ Pivot table — with no formula typing. The formula that does the same job for one category is SUMIF: ```=SUMIF(A2:A10,\"West\",B2:B10)``` totals column B only for rows where column A equals \"West\". ```=COUNTIF(A2:A10,\"West\")``` tells you how many West rows there are."},{"heading":"Worked examples","text":"Let A2:A10 hold regions West, East, West, East, West, East, West, East, West and B2:B10 hold sales 100, 300, 200, 150, 150, 250, 100, 200, 50. Then ```=SUMIF(A2:A10,\"West\",B2:B10)``` adds 100 + 200 + 150 + 100 + 50 = 600, and ```=SUMIF(A2:A10,\"East\",B2:B10)``` adds 300 + 150 + 250 + 200 = 900. ```=COUNTIF(A2:A10,\"West\")``` returns 5. A pivot table with Region in rows and Sum of Sales in values would show exactly West 600, East 900, grand total 1500."},{"heading":"Your turn","text":"With that region/sales data, predict: (1) ```=SUMIF(A2:A10,\"East\",B2:B10)```, (2) ```=COUNTIF(A2:A10,\"East\")```, (3) the pivot grand total of all sales, (4) ```=AVERAGEIF(A2:A10,\"West\",B2:B10)```. Expected: (1) 900, (2) 4, (3) 1500, (4) 120 (600 ÷ 5)."},{"heading":"Common mistakes & exit ticket","text":"Mistake: forgetting to refresh a pivot table after editing the source data — it does not auto-update on refresh in Excel until you click Refresh. Mistake: leaving blank header cells, which breaks the pivot field list. Exit: (a) What does ```=SUMIF(A2:A10,\"West\",B2:B10)``` total? (b) Which two areas of a pivot did we use? Answers: sales for West rows only; rows (Region) and values (Sum of Sales)."}]}'::jsonb, 'A pivot table groups rows by a field and aggregates another; SUMIF is the single-cell formula equivalent.', 13),
  (8, 'Key terms', 'vocab', '{"items":[{"term":"cell reference","translation":"the address of a cell, such as B2, used inside a formula","example":"The formula =A2+B2 uses two cell references."},{"term":"absolute reference","translation":"a reference locked with dollar signs so it does not shift when copied","example":"Anchor a tax rate with $F$1 so it stays put as you fill down."},{"term":"function","translation":"a built-in named formula that takes arguments in parentheses","example":"SUM, AVERAGE, and VLOOKUP are all functions."},{"term":"VLOOKUP","translation":"a function that finds a key in the first column of a table and returns a value from another column","example":"=VLOOKUP(\"Banana\",A2:B5,2,FALSE) returns Banana''s price."},{"term":"pivot table","translation":"a tool that groups records by a field and summarizes another to condense large data","example":"A pivot table totalled sales by region in one click."},{"term":"data validation","translation":"a rule that limits what a cell will accept, such as a dropdown or number range","example":"Data validation kept the status column to Open or Closed only."}]}'::jsonb, null, 8),
  (9, 'Checkpoint 2', 'quiz', '{"questions":[{"prompt":"```=SORT(A2:B10,2,FALSE)``` sorts by the 2nd column in…","options":["ascending order","descending order","random order","alphabetical order only"],"answer":1,"explanation":"The FALSE argument tells SORT to go descending."},{"prompt":"Data validation is used to…","options":["draw charts","restrict what can be entered in a cell","delete duplicate rows","print a sheet"],"answer":1,"explanation":"Validation rules control the values a cell will accept."},{"prompt":"```=FILTER(A2:B10,B2:B10>100)``` returns the rows where…","options":["column B is under 100","column A is text","column B is greater than 100","the sheet is sorted"],"answer":2,"explanation":"FILTER keeps only rows whose condition on column B is true."},{"prompt":"For West sales of 100, 200, 150, 100, 50, ```=SUMIF(A2:A10,\"West\",B2:B10)``` returns…","options":["500","600","900","5"],"answer":1,"explanation":"100 + 200 + 150 + 100 + 50 = 600."},{"prompt":"A pivot table''s main job is to…","options":["encrypt a file","summarize large data by category","translate text","resize columns"],"answer":1,"explanation":"Pivot tables aggregate many rows into a compact grouped summary."},{"prompt":"Which chart type best shows parts of a single whole?","options":["line chart","pie chart","scatter plot","gantt chart"],"answer":1,"explanation":"A pie chart shows how a total splits into proportional slices."}]}'::jsonb, null, 8),
  (10, 'Applied project: build a budget tracker', 'writing', '{"sections":[{"heading":"The task","text":"Build a personal monthly budget tracker in Excel or Google Sheets that uses formulas, a pivot table, and a chart. Set up a table with columns Date, Category (e.g. Rent, Food, Transport, Fun), and Amount, and enter at least fifteen sample transactions across several categories."},{"heading":"Milestones","text":"1) Total all spending with ```=SUM(C2:C16)``` and find your biggest single expense with ```=MAX(C2:C16)```. 2) Total one category with a lookup-style aggregate, e.g. ```=SUMIF(B2:B16,\"Food\",C2:C16)```. 3) Add a data validation dropdown on the Category column so only your four categories can be entered. 4) Insert a pivot table with Category in rows and Sum of Amount in values. 5) Build a chart from the pivot — a pie chart for category share or a bar chart comparing categories."},{"heading":"Self-check rubric","text":"✔ At least one SUM (or AVERAGE) formula returns a correct total you can verify by hand. ✔ A SUMIF (or pivot row) correctly isolates one category. ✔ The Category column rejects a value outside your list. ✔ The pivot''s grand total matches your ```=SUM(C2:C16)```. ✔ The chart is readable and labelled. If all five hold, your tracker is a working, auditable spreadsheet."}]}'::jsonb, null, 15)
) as v(pos, title, kind, body, notes, mins)
where not exists (
  select 1 from public.lessons l
  where l.course_id = 'bbbb0002-0000-4000-8000-00000000000d' and l.position = v.pos
);
